using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace Unscrew.Game
{
    /// <summary>
    /// Minimal stage-4 UI: debug HUD line and a win/lose overlay with Restart/Next.
    /// Generated by "Unscrew/Build Game Scene"; the full meta UI replaces it in stage 5.
    /// </summary>
    public sealed class GameHud : MonoBehaviour
    {
        [SerializeField] private TMP_Text levelText;
        [SerializeField] private TMP_Text debugText;
        [SerializeField] private GameObject overlay;
        [SerializeField] private TMP_Text overlayTitle;
        [SerializeField] private Button restartButton;
        [SerializeField] private Button nextButton;

        private GameFlow _flow;

        public void Bind(GameFlow flow)
        {
            _flow = flow;
            flow.OnLevelStarted += _ => { overlay.SetActive(false); Refresh(); };
            flow.OnMove += Refresh;
            flow.OnWin += _ => ShowOverlay(true);
            flow.OnLose += _ => ShowOverlay(false);
            restartButton.onClick.AddListener(() => _flow.Restart());
            nextButton.onClick.AddListener(() => _flow.NextLevel());
            overlay.SetActive(false);
        }

        private void ShowOverlay(bool won)
        {
            Refresh();
            overlayTitle.text = won ? "Level complete!" : "Out of space!";
            nextButton.gameObject.SetActive(won);
            overlay.SetActive(true);
        }

        private void Refresh()
        {
            if (_flow?.Session == null) return;
            var s = _flow.Level.Settings;
            levelText.text = s.isHard ? $"Level {_flow.LevelNumber}  <color=#FF5A5A>HARD</color>" : $"Level {_flow.LevelNumber}";
            debugText.text =
                $"src {_flow.SourceNumber} | bolts {_flow.Session.Board.RemainingBolts}/{_flow.Level.Definition.bolts.Length} | " +
                $"moves {_flow.Session.MovesMade} | buf {_flow.Session.Collector.BufferUsed}/{_flow.Session.Collector.BufferCapacity} | " +
                $"queue {_flow.Session.Collector.UpcomingColors.Count} | mix {s.mixWindow}";
        }
    }
}
